@spec arrange_page_spec  src=tests/specs/arrange_page_spec.lua  loc=1188  cases=50
@exercises commandManager (h.cmgr), configManager (h.cm), arrangeManager (am)
@surface   cmgr:registerAll, cm:set, cmgr:push, am:tracksTakes, cmgr:invoke, cmgr:installManifest, cmgr:scope, cm:get, am:resizeTake, am:trimHead, am:trackSlots
@harness   mk, reaper:setTrackName, reaper:addItem, reaper:setProjectTracks, reaper.SetMediaItemSelected, reaper:setCursor

# Intent
  Pin-tests for arrangePage's Page interface and arrange-scope edit commands.
  Cursor mechanics, off-screen no-op, and selection-precedence: arrange_view_spec.

# Helpers
  @fn newArrangePage(cm, ds, cmgr, chrome, gui)  @ 49-57
  @fn twoSelected(h)  @ 61-80
      -- Two instances of slot 0, one row each at QN 0 and 1, with rows 0..1 banded.
      -- The siblings at QN 10 and 20 are what slots 0 and 1 clone from.

# Cases
  @case 'bind / unbind are no-ops — arrange page never re-keys cm'  [harness]  @ 84-94
  @case 'the arrange facade enumerates the takes over a span of columns and QN'  [harness]  @ 100-129
  @case 'the arrange facade answers the placement a QN falls in on a track'  [harness]  @ 133-149
  @case 'focusState before any render returns both bits false'  [harness]  @ 153-160
  @case 'arrange-scope is registered at module load (cursorRight invokable)'  [harness]  @ 164-171
  @case 'the manifest declares every command the arrange page registers'  [harness]  @ 178-193
  @case 'arrange-scope place commands are registered (drop0/dropA/dropZ invokable)'  [harness]  @ 197-208
  @case 'a place-command drop advances the cursor by cm.arrangeAdvanceBy rows'  [harness]  @ 212-235
  @case 'arrangeAdvanceBy0..9 set cm.arrangeAdvanceBy at project tier'  [harness]  @ 239-250
  @case 'chained Super-D walks down — each clone becomes the selection for the next'  [harness]  @ 254-273
  @case 'a place-command drop inherits the length of an existing instance'  [harness]  @ 277-299
  @case 'arrangeNudgeForward moves the cursor take by one row'  [harness]  @ 303-317
  @case 'arrangeNudgeForward moves a take taller than one row'  [harness]  @ 321-336
  @case 'arrangeEdgeDown lengthens the cursor take by one row'  [harness]  @ 340-358
  @case 'growing a trimmed take moves its end, leaving the head where it was'  [harness]  @ 362-384
  @case 'arrangeEdgeDown silently no-ops at the take-source length cap'  [harness]  @ 388-403
  @case 'arrangeEdgeUp reduces the cursor take by one row'  [harness]  @ 407-423
  @case 'arrangeDeleteTake removes the cursor take'  [harness]  @ 427-441
  @case 'deleteSlot forever-deletes the cursor take\'s slot behind a confirm'  [harness]  @ 447-471
  @case 'deleteSlot no-ops with the cursor off every take'  [harness]  @ 475-491
  @case 'arrangeNudgeForward is a no-op when the next row is occupied'  [harness]  @ 495-511
  @case 'arrangeNudgeBack is a no-op when the take is already at row 0'  [harness]  @ 515-529
  @case 'arrangeEdgeDown against a flush neighbour stores intent; rendered is gap-capped'  [harness]  @ 533-552
  @case 'arrangeNudgeForward steps past a neighbour without a start-collision'  [harness]  @ 556-576
  @case 'arrangeNudgeForward truncates the displaced take when stepping past'  [harness]  @ 580-602
  @case 'arrangeDive switches to the tracker for the cursor MIDI take'  [harness]  @ 606-621
  @case 'createSlot dives the tracker onto the freshly-minted take'  [harness]  @ 625-640
  @case 'arrangeDive over an audio take still switches and restores (no take pinned)'  [harness]  @ 644-658
  @case 'arrangeDive over empty space switches and restores'  [harness]  @ 662-674
  @case 'the dive carries the caret QN, and carries none over empty space'  [harness]  @ 680-699
  @case 'kb edit acts on the cursor take when nothing is selected'  [harness]  @ 703-721
  @case 'kb delete no-ops when the cursor sits off every take'  [harness]  @ 725-743
  @case 'kb nudge no-ops when cursor sits on empty space'  [harness]  @ 747-764
  @case 'an edit command is a no-op when the cursor is over empty space'  [harness]  @ 768-783
  @case 'a second delete finds an empty cell under the cursor — no-op'  [harness]  @ 787-805
  @case 'seedCursorFromReaper lands the cursor on the selected take'  [harness]  @ 809-826
  @case 'seedCursorFromReaper falls back to the edit-cursor row'  [harness]  @ 830-844
  @case 'arrangeTakeProperties routes the focused MIDI take through the tracker facade'  [harness]  @ 853-866
  @case 'arrangeTakeProperties is a no-op on an audio take'  [harness]  @ 870-883
  @case 'arrangeDuplicateBelow drops a pooled clone at the focused take\'s append point'  [harness]  @ 887-903
  @case 'arrangeDuplicateBelow is silent for want of room and on audio takes'  [harness]  @ 907-925
  @case 'arrangeNextVariant past the last of the family swaps the target for a fresh variant'  [harness]  @ 929-960
  @case 'arrangeDuplicateBelow then arrangeNextVariant forks the copy onto a fresh slot'  [harness]  @ 966-990
  @case 'replace mode: a drop swaps the take under the cursor, keeping its start'  [harness]  @ 996-1023
  @case 'a replace with a selection held replaces every selected take'  [harness]  @ 1027-1044
  @case 'the replacements become the selection'  [harness]  @ 1048-1060
  @case 'a shorter replacement pulls the cursor back inside it'  [harness]  @ 1064-1092
  @case 'replace mode disarms on the drop it reinterprets — the next drop places'  [harness]  @ 1096-1124
  @case 'a cursor move disarms replace mode'  [harness]  @ 1128-1154
  @case 'a second arrangeReplaceMode disarms — the mode is a toggle'  [harness]  @ 1158-1185

